WITH Src AS (SELECT *, SUBSTRING(city, 1, 2) AS city_prefix FROM suppliers WHERE LENGTH(supplier_name) < 13), summary AS (SELECT CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(CASE WHEN city = 'Tokyo' THEN 1 END) AS tokyo_count FROM Src GROUP BY CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END) SELECT * FROM summary ORDER BY rating_bucket DESC;
